"""Collect the final-evaluation numbers into RESULTS.md (generated; do not edit by hand)."""
import csv
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import *  # noqa: F401,F403

R = lambda f: list(csv.DictReader(open(os.path.join(RESULTS, f))))


def num(x, nd=2):
    try:
        return f"{float(x):.{nd}f}"
    except (TypeError, ValueError):
        return str(x)


def pct(x):
    try:
        return f"{100 * float(x):+.1f}%"
    except (TypeError, ValueError):
        return ""


def table(header, rows):
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def main():
    md = ["# Final-evaluation results (generated by experiments/make_results_md.py)", "",
          "All numbers below are produced by `./run_final.sh`; figures are in `experiments/figures/`.",
          "Platform unless stated: 1x H100-class GPU, 80 GB HBM3 (3.35 TB/s), Mixtral-8x7B FP16, all",
          "experts in off-chip CPU DRAM behind a 900 GB/s NVLink-C2C link (SSD-offloading `offload_bandwidth: 5`).",
          "Expert = 352.3 MB, load 391.5 us, execution of 1 token ~144 us (HBM bandwidth minus link bandwidth).", ""]

    # ---------------------------------------------------------------- validation
    v = R("validate_costs.csv")
    runs = [r for r in v if r["run"].startswith(("H100", "A100"))]
    worst = max(max(float(r["max_rel_err_exec"]), float(r["max_rel_err_load"])) for r in runs)
    wb = max(float(r["max_rel_err_offload_bytes"]) for r in runs)
    ok = all(r["routing_log_matches_trace"] == "True" for r in runs)
    m = [r for r in v if r["run"].startswith("midterm")][0]
    md += ["## V. Validation", "",
           f"* {len(runs)} simulated batches ({2 * len(runs)} simulator runs, compute + copy mode); routing executed"
           f" by the simulator == routing trace: **{ok}**.",
           f"* Timeline cost model vs simulator `expert_ffn` (compute and copy mode), worst relative error **{worst:.1e}**;"
           f" offload bytes vs `moe_offload` energy: {wb:.1e} (float32 energy constants).",
           f"* Midterm D2 configs re-run on the modified simulator: load {num(m['midterm_load_ms'])} ms,"
           f" exec {num(m['midterm_exec_ms'])} ms, max relative difference to the committed midterm CSVs"
           f" {float(m['max_rel_diff_vs_committed_midterm_csv']):.1e}.", ""]

    # ---------------------------------------------------------------- F0
    f0 = R("f0_correlation.csv")
    md += ["## F0. Temporal / spatial correlation of the workloads", "",
           table(["workload", "token overlap", "same-id layer overlap", "NMI top-1 l->l+1", "NMI top-1 t->t+1",
                  "rep. 1st-or-2nd L0/L15/L31", "top expert share", "distinct experts/layer B=4"],
                 [[r["workload"], num(r.get("token_overlap"), 3), num(r.get("layer_overlap_same_id"), 3),
                   num(r.get("nmi_top1_layer_l_to_l+1"), 3), num(r.get("nmi_top1_token_t_to_t+1"), 3),
                   "/".join(num(r.get(f"rep_first_or_second_L{l}"), 3) for l in (0, 15, 31)),
                   num(r.get("top_expert_share"), 3), num(r.get("distinct_experts_B4"), 2)] for r in f0]), ""]

    # ---------------------------------------------------------------- F1
    f1 = R("f1_accuracy.csv")
    md += ["## F1. Predictor accuracy vs the routed experts (batch 1, lookahead d = 1)", "",
           "recall = |P∩A|/|A| (overlap accuracy), precision = |P∩A|/|P|, coverage = P(A ⊆ P).", ""]
    rows = []
    for w in WORKLOADS:
        for p in ("random", "frequency", "temporal", "spatial", "st-hybrid", "st-moe", "spec-gate", "spec-hybrid"):
            for r in f1:
                if r["workload"] == w and r["predictor"] == p and r["batch"] == "1" and r["lookahead"] == "1" \
                        and r["budget"] in ("top-2", "ST-MoE score>=2 (variable set)"):
                    rows.append([w, p, r["budget"], num(r["recall"], 3), num(r["precision"], 3),
                                 num(r["full_coverage"], 3), num(r["prefetch_set"], 2)])
    md += [table(["workload", "predictor", "budget", "recall", "precision", "full coverage", "|P|"], rows), ""]
    rows = []
    for r in f1:
        if r["predictor"] == "spec-hybrid" and r["batch"] == "1" and r["workload"].startswith("tinymoe-prose"):
            rows.append([r["workload"], r["lookahead"], r["budget"], num(r["recall"], 3), num(r["precision"], 3),
                         num(r["full_coverage"], 3), num(r["prefetch_set"], 2)])
    md += ["Budget / lookahead sweep (spec-hybrid, tinymoe-prose, batch 1):", "",
           table(["workload", "d", "budget", "recall", "precision", "full coverage", "|P|"], rows), ""]
    bs = R("f1_beta_sweep.csv")
    md += ["Mixtral-calibrated cross-layer strength sweep (top-2, d = 1):", "",
           table(["beta", "Table-5 max abs error", "predictor", "recall", "coverage"],
                 [[r["beta"], num(r["table5_max_abs_error"], 3), r["predictor"], num(r["recall"], 3),
                   num(r["full_coverage"], 3)] for r in bs]), ""]

    # ---------------------------------------------------------------- F2/F3
    s = R("f2_summary.csv")
    md += ["## F2-F4. Prefetching vs on-demand execution", "",
           "Latency per decode step (= per generated token of each sequence), expert-load time (link busy",
           "copying experts), exposed expert-load stall (GPU idle waiting for a copy),",
           "DRAM->HBM traffic, energy per generated token.  Speed-up / savings relative to on-demand + LRU",
           "at the same cache capacity.  Mean over independent sequence groups (H100: B=1 16, B=4 8, B=8 4 groups;",
           "B=4/8 use all 32 evaluation sequences; A100 and the ablation: 8 groups at B=1), with the min-max",
           "speed-up over groups in brackets.", ""]
    for B in ("1", "4", "8"):
        for w in WORKLOADS:
            rows = [r for r in s if r["experiment"] == "main" and r["platform"] == "H100-NVL5"
                    and r["workload"] == w and r["batch"] == B]
            if not rows:
                continue
            serial = float(rows[0]["sim_serial_on_demand_ms_per_step"])
            md += [f"### {w}, batch {B} (H100, 900 GB/s)", "",
                   f"Simulator's own serial on-demand estimate (attention + all expert loads + all expert executions,"
                   f" no overlap, no reuse): **{serial:.2f} ms/step**.", ""]
            body = []
            for r in sorted(rows, key=lambda r: (int(r["capacity"]), r["policy"])):
                body.append([r["capacity"], r["policy"], num(r["latency_ms_per_step"]), num(r["expert_load_ms_per_step"]),
                             num(r["stall_ms_per_step"]),
                             num(r["hit_rate"], 2), num(r["prefetch_accuracy"], 2),
                             num(r["prefetch_eventual_use"], 2), num(r["traffic_gb_per_step"]),
                             num(r["energy_j_per_token"]),
                             num(r.get("speedup_vs_od_lru"), 3) + (f" ({num(r['speedup_min_over_groups'], 2)}-"
                                                                    f"{num(r['speedup_max_over_groups'], 2)})"
                                                                    if r.get("speedup_min_over_groups") else ""),
                             pct(r.get("stall_reduction_vs_od_lru")), pct(r.get("energy_saving_vs_od_lru")),
                             pct(r.get("extra_traffic_vs_od_lru"))])
            md += [table(["cache", "policy", "ms/step", "expert-load ms", "stall ms", "hit", "pf acc", "pf used", "GB/step", "J/token",
                          "speed-up (range over groups)", "stall red.", "energy saving", "extra traffic"], body), ""]
    ab = [r for r in s if r["experiment"] == "ablation"]
    if ab:
        md += ["### Ablation (batch 1, H100)", ""]
        body = [[r["workload"], r["capacity"], r["policy"], num(r["latency_ms_per_step"]),
                 num(r.get("speedup_vs_od_lru"), 3), num(r["traffic_gb_per_step"]), pct(r.get("energy_saving_vs_od_lru"))]
                for r in sorted(ab, key=lambda r: (r["workload"], int(r["capacity"]), r["policy"]))]
        md += [table(["workload", "cache", "variant", "ms/step", "speed-up", "GB/step", "energy saving"], body), ""]
    a100 = [r for r in s if r["platform"] == "A100-NVL4" and r["experiment"] == "main"]
    if a100:
        md += ["### A100-class 80 GB HBM (2.04 TB/s), NVLink 4.0 450 GB/s", ""]
        body = [[r["workload"], r["batch"], r["capacity"], r["policy"], num(r["latency_ms_per_step"]),
                 num(r["stall_ms_per_step"]), num(r.get("speedup_vs_od_lru"), 3), pct(r.get("energy_saving_vs_od_lru"))]
                for r in sorted(a100, key=lambda r: (r["workload"], int(r["batch"]), int(r["capacity"]), r["policy"]))]
        md += [table(["workload", "B", "cache", "policy", "ms/step", "stall ms", "speed-up", "energy saving"], body), ""]
    with open(os.path.join(ROOT, "RESULTS.md"), "w") as f:
        f.write("\n".join(md) + "\n")
    print("wrote RESULTS.md")


if __name__ == "__main__":
    main()
